pub(super) struct State {
    pub size: [u32; 2],
    pub generation: u64,
    color: Image,
    depth: Image,
    primitive: Image,
    pipeline: wgpu::RenderPipeline,
    highlight: wgpu::RenderPipeline,
    clip_buffer: wgpu::Buffer,
    clip_group: wgpu::BindGroup,
    outline: crate::course_image_outline::Outline,
    outline_key: Option<(u64,usize,usize)>,
}

pub(crate) fn enabled() -> bool {
    #[cfg(target_arch = "wasm32")]
    {
        let window = web_sys::window().expect("Image coverage window");
        let value = js_sys::Reflect::get(window.as_ref(), &wasm_bindgen::JsValue::from_str("__courseImageCapSamples")).expect("Image sample profile");
        if value.is_undefined() { return false; }
        assert_eq!(value.as_f64(), Some(4.0));
        true
    }
    #[cfg(not(target_arch = "wasm32"))]
    { false }
}

impl State {
    pub fn new(r: &Renderer, generation: u64) -> Self {
        let device = &r.device;
        let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("course image surfaces"),
            source: wgpu::ShaderSource::Wgsl(crate::clipping_gpu::source(include_str!("course_image_triangle.wgsl"), 2, 0).into()),
        });
        let layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("course image surfaces"),
            bind_group_layouts: &[Some(&crate::gpu_layout::uniform(device, 80)), Some(&crate::gpu_layout::uniform(device, 160)),
                Some(&crate::clipping_gpu::layout(device)), Some(&crate::gpu_geometry::GpuGeometry::storage_layout(device))], immediate_size: 0,
        });
        let pipeline = |depth, write| device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
            label: Some("course image surfaces"), layout: Some(&layout),
            vertex: wgpu::VertexState { module: &shader, entry_point: Some("vertex"), compilation_options: Default::default(), buffers: &[] },
            fragment: Some(wgpu::FragmentState { module: &shader, entry_point: Some("fragment"), compilation_options: Default::default(),
                targets: &[Some(wgpu::ColorTargetState { format: r.format, blend: Some(wgpu::BlendState::ALPHA_BLENDING), write_mask: wgpu::ColorWrites::ALL }), Some(crate::primitive_image::target(write))] }),
            primitive: Default::default(), depth_stencil: Some(depth), multisample: wgpu::MultisampleState { count: 4, ..Default::default() }, multiview_mask: None, cache: None,
        });
        let clip_buffer = device.create_buffer_init(&wgpu::util::BufferInitDescriptor {
            label: Some("course image clipping"), contents: &[0;448], usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
        });
        let clip_group = crate::gpu_layout::group(device, &crate::clipping_gpu::layout(device), &clip_buffer);
        Self { size: r.size, generation, color: Image::new(device, r.size, r.format, 4), depth: Image::new(device, r.size, crate::depth::FORMAT, 4),
            primitive: Image::new(device, r.size, crate::primitive_image::FORMAT, 4), pipeline: pipeline(crate::depth::surface(), true),
            highlight: pipeline(crate::depth::ink(), false), clip_buffer, clip_group,
            outline: crate::course_image_outline::Outline::new(&r.text_context(), r.format), outline_key: None }
    }

    pub fn draw(&mut self, r: &Renderer, encoder: &mut wgpu::CommandEncoder, output: &wgpu::TextureView, background: &crate::background::Background, transform: &[f32;16]) {
        assert_eq!(self.size, r.size);
        assert_eq!(r.meshes.len(), 2);
        assert!(r.instance_rows.is_empty());
        assert!(!r.outlines_enabled.get());
        assert_eq!(r.opacity.get(), 1.0);
        let clip = r.clipping.borrow();
        assert!(clip.enabled && clip.solid && clip.error.is_none());
        assert_eq!(clip.rows.len(), 1);
        let matrix = session_rust::Xform::from_matrix((*transform).map(f64::from));
        let planes = clip.rows.iter().map(|row| row.plane).collect::<Vec<_>>();
        let uniform = crate::clipping_uniform::clip_uniform(&planes, 1, &crate::clipping_uniform::ClipView {
            view_proj: &matrix, anchor: [0.;3], height: r.size[1], pixel_scale: f64::from(r.density), samples: 4, forward_depth: true,
        });
        r.queue.write_buffer(&self.clip_buffer, 0, &crate::clipping_gpu::bytes(&uniform));
        drop(clip);
        assert_eq!(self.color.texture.sample_count(), 4);
        assert_eq!(self.depth.texture.sample_count(), 4);
        assert_eq!(self.primitive.texture.sample_count(), 4);
        let [red, green, blue] = background.rgb();
        {
            let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                label: Some("course image coherent surfaces"),
                color_attachments: &[
                    Some(wgpu::RenderPassColorAttachment { view: &self.color.view, depth_slice: None, resolve_target: None,
                        ops: wgpu::Operations { load: wgpu::LoadOp::Clear(wgpu::Color { r: red, g: green, b: blue, a: 1.0 }), store: wgpu::StoreOp::Store } }),
                    Some(wgpu::RenderPassColorAttachment { view: &self.primitive.view, depth_slice: None, resolve_target: None,
                        ops: wgpu::Operations { load: wgpu::LoadOp::Clear(wgpu::Color::TRANSPARENT), store: wgpu::StoreOp::Store } }),
                ],
                depth_stencil_attachment: Some(wgpu::RenderPassDepthStencilAttachment { view: &self.depth.view,
                    depth_ops: Some(wgpu::Operations { load: wgpu::LoadOp::Clear(1.0), store: wgpu::StoreOp::Store }), stencil_ops: None }),
                ..Default::default()
            });
            pass.set_bind_group(2, &self.clip_group, &[]); pass.set_bind_group(0, &r.view_group, &[]);
            pass.set_pipeline(&self.pipeline);
            for mesh in &r.meshes { mesh.draw_pulled(&mut pass); }
            pass.set_pipeline(&self.highlight); r.highlight.mesh(&mut pass);
        }
        r.caps.borrow_mut().draw_image4(&r.device, r.format, r.size, encoder, &self.color.view, &self.primitive.view, &self.depth.view, &r.view_group, &self.clip_group, &r.meshes, 1);
        {
            let _pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                label: Some("course image same-size color resolve"),
                color_attachments: &[Some(wgpu::RenderPassColorAttachment { view: &self.color.view, depth_slice: None, resolve_target: Some(output),
                    ops: wgpu::Operations { load: wgpu::LoadOp::Load, store: wgpu::StoreOp::Store } })], ..Default::default()
            });
        }
    }

    pub fn selected(&mut self, r: &Renderer, encoder: &mut wgpu::CommandEncoder, output: &wgpu::TextureView, transform: &[f32;16], revision: u64) {
        let key=(r.pyramid_revision,r.settings_writes,r.settings_allocations);
        if self.outline_key!=Some(key) { self.outline.invalidate(); self.outline_key=Some(key); }
        if r.meshes.iter().any(GpuMesh::selected) {
            self.outline.encode(&r.text_context(), encoder, output, &self.depth.view, &r.view_group, &r.meshes, *transform, r.size, r.density, &self.clip_group, revision);
        }
        #[cfg(target_arch="wasm32")]
        web_sys::window().and_then(|window| window.document()).and_then(|document| document.get_element_by_id("canvas")).expect("Image canvas")
            .set_attribute("data-image-cap-coverage", &serde_json::json!({"samples":4,"querySamples":1,"internal":r.size,
                "attachments":{"color":4,"depth":4,"primitive":4,"crossings":4,"selectedCoverage":4},
                "colorResolve":"same-size","integerResolve":false,"queryTargetsUntouched":true,
                "allocationGeneration":self.generation,"deviceScope":"owning-Renderer","extraTexelAndBufferBytes":u64::from(r.size[0])*u64::from(r.size[1])*60+self.outline.usage()[0]+448}).to_string()).expect("Image coverage proof");
    }
}

pub(super) struct Present {
    source: Image,
    size: [u32; 2],
    format: wgpu::TextureFormat,
    pipeline: wgpu::RenderPipeline,
    binding: wgpu::BindGroup,
}
impl Present {
    fn new(renderer: &Renderer, format: wgpu::TextureFormat, shader: &str) -> Self {
        let device = &renderer.device;
        let source = Image::new(device, renderer.size, format, 1);
        let shader = device.create_shader_module(wgpu::ShaderModuleDescriptor {
            label: Some("cached image presentation"), source: wgpu::ShaderSource::Wgsl(shader.into()),
        });
        let pipeline = device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
            label: Some("cached image presentation"), layout: None,
            vertex: wgpu::VertexState { module: &shader, entry_point: Some("vertex"), buffers: &[], compilation_options: Default::default() },
            fragment: Some(wgpu::FragmentState { module: &shader, entry_point: Some("fragment"),
                targets: &[Some(wgpu::ColorTargetState { format, blend: None, write_mask: wgpu::ColorWrites::ALL })], compilation_options: Default::default() }),
            primitive: Default::default(), depth_stencil: None, multisample: Default::default(), multiview_mask: None, cache: None,
        });
        let sampler = device.create_sampler(&wgpu::SamplerDescriptor {min_filter:wgpu::FilterMode::Linear,mag_filter:wgpu::FilterMode::Linear,..Default::default()});
        let binding = device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("cached image presentation"), layout: &pipeline.get_bind_group_layout(0),
            entries: &[
                wgpu::BindGroupEntry {binding:0,resource:wgpu::BindingResource::TextureView(&source.view)},
                wgpu::BindGroupEntry {binding:1,resource:wgpu::BindingResource::Sampler(&sampler)},
            ],
        });
        Self {source,size:renderer.size,format,pipeline,binding}
    }
}
impl Renderer {
    pub(crate) fn course_image_present(&self, output:&wgpu::Texture, view:&wgpu::TextureView, background:&crate::background::Background, transform:&[f32;16], normals:bool, shader:&str) {
        assert!(enabled());
        let format=output.format().add_srgb_suffix();
        assert!(matches!(format,wgpu::TextureFormat::Rgba8UnormSrgb|wgpu::TextureFormat::Bgra8UnormSrgb));
        assert_eq!(self.format,format);
        assert_eq!(self.size,[output.width().checked_mul(2).unwrap(),output.height().checked_mul(2).unwrap()]);
        let mut cache=self.course_present.borrow_mut();
        let present=cache.get_or_insert_with(||Present::new(self,format,shader));
        assert_eq!(present.size,self.size,"Bounded image presentation rejects a later resize");
        assert_eq!(present.format,format);
        self.draw_mode(&present.source.view,background,transform,normals);
        let mut encoder=self.device.create_command_encoder(&Default::default());
        {
            let mut pass=encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                label:Some("cached image output"),
                color_attachments:&[Some(wgpu::RenderPassColorAttachment {view,depth_slice:None,resolve_target:None,
                    ops:wgpu::Operations {load:wgpu::LoadOp::Clear(wgpu::Color::TRANSPARENT),store:wgpu::StoreOp::Store}})],..Default::default()
            });
            pass.set_pipeline(&present.pipeline);pass.set_bind_group(0,&present.binding,&[]);pass.draw(0..3,0..1);
        }
        self.queue.submit([encoder.finish()]);
        #[cfg(target_arch="wasm32")]
        web_sys::window().and_then(|window|window.document()).and_then(|document|document.get_element_by_id("canvas")).expect("Image canvas")
            .set_attribute("data-image-gpu-present",&serde_json::json!({"presentation":"linear-srgb-gpu","filter":"linear",
                "format":format!("{format:?}"),"samples":1,"internal":self.size,"output":[output.width(),output.height()],"panel":"output-resolution"}).to_string()).expect("Image presentation proof");
    }
}

